CREATE VIEW registry_source."discharge_report"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "breg_f_discharge_report_installation_b8fdf5cd5dd9338a" AS "installation", "breg_f_discharge_report_administrative_boundar_d49eb22230deabc2" AS "administrative_boundary", "breg_f_discharge_report_substance_code_a4a5e041372da022" AS "substance_code", "breg_f_discharge_report_period_start_253a33cf5f977a06" AS "period_start", "breg_f_discharge_report_period_end_4d14da0593362c91" AS "period_end", "breg_f_discharge_report_quantity_value_1c374b4b0917aa34" AS "quantity_value", "breg_f_discharge_report_quantity_unit_242094e47e71dc38" AS "quantity_unit"
                    FROM registry_data."breg_e_discharge_report_3406e17df0820568"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."facility"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "breg_f_facility_facility_code_fcdd21b7440c580b" AS "facility_code", "breg_f_facility_display_name_b8bb523e48bcac60" AS "display_name", "breg_f_facility_administrative_boundary_4d133c3cbadc9f66" AS "administrative_boundary"
                    FROM registry_data."breg_e_facility_675cdbdae206c49c"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."installation"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "breg_f_installation_installation_code_a860d099ef50d4a0" AS "installation_code", "breg_f_installation_permit_b1652780339e8d80" AS "permit", "breg_f_installation_administrative_boundary_bb9a62859b97b50b" AS "administrative_boundary", "breg_f_installation_centroid_a4fd950cd3a07de8" AS "centroid", "breg_f_installation_area_value_4b154697a8c784f4" AS "area_value", "breg_f_installation_area_unit_4527c90cd23116b3" AS "area_unit", "breg_f_installation_import_source_fd02b4ebbab3eb94" AS "import_source", "breg_f_installation_source_record_id_e14cead7f3e8f58e" AS "source_record_id"
                    FROM registry_data."breg_e_installation_47f439840ea4b79b"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_source."permit"
                 WITH (security_invoker=true, security_barrier=true)
                 AS SELECT record_id AS "id", "breg_f_permit_permit_number_675b61a963895cb2" AS "permit_number", "breg_f_permit_facility_6043415cce54d323" AS "facility", "breg_f_permit_permit_type_ab81b57b4c0e7132" AS "permit_type", "breg_f_permit_valid_from_fd668fac0a7e4239" AS "valid_from", "breg_f_permit_valid_to_adb872395da24ccd" AS "valid_to", "breg_f_permit_administrative_boundary_ee8b9f1fe5600c56" AS "administrative_boundary", "breg_f_permit_import_source_a6e99febe9e88053" AS "import_source", "breg_f_permit_source_record_id_e9dba1afa5387efe" AS "source_record_id"
                    FROM registry_data."breg_e_permit_c41383d96b950de7"
                   WHERE record_lifecycle = 'active';
CREATE VIEW registry_derived."discharge_report__discharge_statistics"
                     WITH (security_invoker=true, security_barrier=true)
                     AS SELECT "__registry$derived$key" AS "id", "has_measured_quantity"::boolean AS "has_measured_quantity"
                        FROM (
                            SELECT canonical_derived.*,
                                   count(*) OVER (PARTITION BY canonical_derived."__registry$derived$key") AS "__registry$derived$cardinality"
                              FROM (
                                  SELECT trusted_derived.*,
                                         trusted_derived."id"::uuid AS "__registry$derived$key"
                                    FROM (SELECT
  report.id AS id,
  report.quantity_value IS NOT NULL AS has_measured_quantity
FROM registry_source.discharge_report AS report) AS trusted_derived
                              ) AS canonical_derived
                        ) AS checked_derived
                       WHERE CASE
                           WHEN "__registry$derived$key" IS NOT NULL AND "__registry$derived$cardinality" = 1 THEN true
                           -- PostgreSQL has no scalar ASSERT. This row-dependent
                           -- expression raises one stable, value-free error for
                           -- a null or duplicate canonical key.
                           ELSE 1 / ("__registry$derived$cardinality" - "__registry$derived$cardinality") = 0
                       END;
CREATE VIEW registry_derived."permit__permit_statistics"
                     WITH (security_invoker=true, security_barrier=true)
                     AS SELECT "__registry$derived$key" AS "id", "expiring_soon"::boolean AS "expiring_soon"
                        FROM (
                            SELECT canonical_derived.*,
                                   count(*) OVER (PARTITION BY canonical_derived."__registry$derived$key") AS "__registry$derived$cardinality"
                              FROM (
                                  SELECT trusted_derived.*,
                                         trusted_derived."id"::uuid AS "__registry$derived$key"
                                    FROM (SELECT
  permit.id AS id,
  CASE
    WHEN permit.valid_to IS NULL THEN false
    ELSE permit.valid_to <= registry_context.evaluation_date() + interval '90 days'
  END AS expiring_soon
FROM registry_source.permit AS permit) AS trusted_derived
                              ) AS canonical_derived
                        ) AS checked_derived
                       WHERE CASE
                           WHEN "__registry$derived$key" IS NOT NULL AND "__registry$derived$cardinality" = 1 THEN true
                           -- PostgreSQL has no scalar ASSERT. This row-dependent
                           -- expression raises one stable, value-free error for
                           -- a null or duplicate canonical key.
                           ELSE 1 / ("__registry$derived$cardinality" - "__registry$derived$cardinality") = 0
                       END;
